CREATE OR REPLACE FUNCTION public.quillmd_disposition_reference()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND NEW.encounter_id IS NOT DISTINCT FROM OLD.encounter_id THEN
  IF EXISTS(SELECT 1 FROM core_dispositiontombstone WHERE target_id=NEW.encounter_id)
  THEN RAISE EXCEPTION 'A disposed target cannot process clinical work'; END IF;
  RETURN NEW;
 END IF;
 -- Source row first: an insert that waited for disposition observes its committed
 -- tombstone before creating any job, reservation-bearing batch, or suggestion.
 IF NEW.encounter_id IS NOT NULL THEN
  PERFORM id FROM core_encounter WHERE id=NEW.encounter_id FOR KEY SHARE;
  IF EXISTS(SELECT 1 FROM core_dispositiontombstone WHERE target_id=NEW.encounter_id)
  THEN RAISE EXCEPTION 'A disposed target cannot acquire clinical work'; END IF;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.quillmd_preserve_clinical_row()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE prior jsonb; dept uuid; pat uuid; enc uuid; org uuid; held jsonb; matched uuid[];
BEGIN
 IF current_setting('transaction_isolation') <> 'read committed' THEN
  RAISE EXCEPTION 'Preservation requires read committed isolation';
 END IF;
 PERFORM pg_advisory_xact_lock(716849203517);
 prior=to_jsonb(OLD);
 IF TG_TABLE_NAME='core_encounter' THEN
  IF TG_OP='DELETE' AND OLD.status='finalized' THEN RAISE EXCEPTION 'Finalized document cannot be deleted'; END IF;
  dept=OLD.department_id; pat=OLD.patient_id; enc=OLD.id;
 ELSIF TG_TABLE_NAME='core_patient' THEN dept=OLD.department_id; pat=OLD.id;
 ELSIF TG_TABLE_NAME='core_template' THEN dept=OLD.department_id;
 ELSIF TG_TABLE_NAME='core_department' THEN dept=OLD.id; org=OLD.organization_id;
 ELSIF TG_TABLE_NAME='core_job' THEN
  enc=OLD.encounter_id;
  IF enc IS NULL THEN
   SELECT t.department_id INTO dept FROM core_templateversion v JOIN core_template t ON t.id=v.template_id WHERE v.id=OLD.mapping_version_id;
  END IF;
 ELSIF TG_TABLE_NAME IN ('core_codesuggestion','core_generationbatch') THEN enc=OLD.encounter_id;
 END IF;
 IF enc IS NOT NULL AND dept IS NULL THEN SELECT department_id,patient_id INTO dept,pat FROM core_encounter WHERE id=enc; END IF;
 IF org IS NULL AND dept IS NOT NULL THEN SELECT organization_id INTO org FROM core_department WHERE id=dept; END IF;
 -- Historical identity remains fixed: releasing a hold is not an instruction
 -- to transfer its evidence to another patient/department. Include ancestor
 -- metadata whose movement would detach a held descendant from its old scope.
 SELECT array_agg(h.id ORDER BY h.id) INTO matched FROM core_retentionhold h
 WHERE h.scope='global' OR h.organization_id=org OR h.department_id=dept OR h.patient_id=pat OR h.encounter_id=enc
 OR (TG_TABLE_NAME='core_patient' AND h.encounter_id IN (SELECT id FROM core_encounter WHERE patient_id=pat))
 OR (TG_TABLE_NAME='core_department' AND (
   h.patient_id IN (SELECT id FROM core_patient WHERE department_id=dept)
   OR h.encounter_id IN (SELECT id FROM core_encounter WHERE department_id=dept)))
 OR (TG_TABLE_NAME='core_template' AND (
   h.encounter_id IN (SELECT e.id FROM core_encounter e JOIN core_templateversion v ON v.id=e.template_version_id WHERE v.template_id=OLD.id)
   OR h.patient_id IN (SELECT e.patient_id FROM core_encounter e JOIN core_templateversion v ON v.id=e.template_version_id WHERE v.template_id=OLD.id)));
 IF matched IS NOT NULL AND TG_OP='UPDATE' AND (
    (prior->'department_id') IS DISTINCT FROM (to_jsonb(NEW)->'department_id') OR
    (prior->'organization_id') IS DISTINCT FROM (to_jsonb(NEW)->'organization_id') OR
    (prior->'patient_id') IS DISTINCT FROM (to_jsonb(NEW)->'patient_id') OR
    (prior->'encounter_id') IS DISTINCT FROM (to_jsonb(NEW)->'encounter_id') OR
    (prior->'mapping_version_id') IS DISTINCT FROM (to_jsonb(NEW)->'mapping_version_id')
 ) THEN RAISE EXCEPTION 'Preserved clinical scope cannot move'; END IF;
 SELECT jsonb_agg(h.id ORDER BY h.id) INTO held FROM core_retentionhold h
 WHERE h.id=ANY(matched) AND NOT EXISTS (SELECT 1 FROM core_retentionholdrelease r WHERE r.hold_id=h.id);
 IF held IS NOT NULL THEN
  INSERT INTO core_preservedrecord(id,created_at,source_table,source_id,operation,hold_ids,prior_record)
   VALUES(gen_random_uuid(),clock_timestamp(),TG_TABLE_NAME,OLD.id,TG_OP,held,prior);
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.quillmd_redaction_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE target core_encounter; body jsonb; org uuid;
BEGIN
 IF current_setting('transaction_isolation') <> 'read committed' THEN
  RAISE EXCEPTION 'Redaction requires read committed isolation';
 END IF;
 IF TG_TABLE_NAME='core_redactionrequest' THEN
  IF NOT EXISTS(SELECT 1 FROM core_user WHERE id=NEW.created_by_id AND is_active AND is_staff AND verified_at IS NOT NULL)
  THEN RAISE EXCEPTION 'A verified redaction custodian is required'; END IF;
  SELECT * INTO target FROM core_encounter WHERE id=NEW.encounter_id;
  IF target.id IS NULL OR target.department_id IS DISTINCT FROM NEW.department_id OR target.status NOT IN ('draft','review')
     OR NEW.reason_sha256 !~ '^[0-9a-f]{64}$' OR NEW.content_sha256 !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'Only an unfinalized document of its own department can be requested for redaction'; END IF;
  RETURN NEW;
 END IF;
 IF TG_TABLE_NAME='core_redactiontombstone' THEN
  -- Source row first, then the preservation lock: the global lock order of core/retention.py.
  PERFORM id FROM core_encounter WHERE id=NEW.target_id FOR UPDATE;
  PERFORM pg_advisory_xact_lock(716849203517);
  body=NEW.journal_entry->'body'->'redaction';
  IF NEW.entry_sha256 !~ '^[0-9a-f]{64}$' OR COALESCE(NEW.journal_entry->>'signature','') !~ '^[0-9a-f]{128}$'
     OR NEW.journal_entry->'body'->>'contract' IS DISTINCT FROM 'redaction-journal-entry-v1'
     OR body->>'id' IS DISTINCT FROM NEW.id::text OR body->>'target_id' IS DISTINCT FROM NEW.target_id::text
     OR body->>'department_id' IS DISTINCT FROM NEW.department_id::text
     OR body->>'request_id' IS DISTINCT FROM NEW.request_id::text
     OR body->>'content_sha256' IS DISTINCT FROM NEW.content_sha256 OR (body->'files') IS DISTINCT FROM NEW.files
     OR body->>'requested_by' IS NOT DISTINCT FROM body->>'approved_by'
  THEN RAISE EXCEPTION 'Invalid redaction tombstone identity'; END IF;
  SELECT * INTO target FROM core_encounter WHERE id=NEW.target_id;
  IF target.id IS NOT NULL THEN
   IF target.status NOT IN ('draft','review') OR target.department_id IS DISTINCT FROM NEW.department_id
   THEN RAISE EXCEPTION 'Only an unfinalized document of its own department can be redacted'; END IF;
   SELECT organization_id INTO org FROM core_department WHERE id=target.department_id;
   IF EXISTS(SELECT 1 FROM core_retentionhold h WHERE NOT EXISTS(SELECT 1 FROM core_retentionholdrelease r WHERE r.hold_id=h.id)
      AND (h.scope='global' OR h.organization_id=org OR h.department_id=target.department_id
           OR h.patient_id=target.patient_id OR h.encounter_id=target.id))
   THEN RAISE EXCEPTION 'A retention hold applies; this content cannot be redacted'; END IF;
   IF EXISTS(SELECT 1 FROM core_generationbatch b WHERE b.encounter_id=target.id)
   THEN RAISE EXCEPTION 'A generation batch keeps this document''s notes; it cannot be redacted'; END IF;
  END IF;
  RETURN NEW;
 END IF;
 IF TG_TABLE_NAME='core_encounter' THEN
  IF EXISTS(SELECT 1 FROM core_redactiontombstone WHERE target_id=NEW.id) AND (NEW.status IS DISTINCT FROM 'redacted'
     OR NEW.notes<>'' OR NEW.answers IS DISTINCT FROM '{}'::jsonb OR NEW.template_review IS DISTINCT FROM '{}'::jsonb
     OR NEW.export_path<>'' OR NEW.export_sha256<>'')
  THEN RAISE EXCEPTION 'A redacted document cannot regain clinical content'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.encounter_id IS NOT NULL THEN
  PERFORM id FROM core_encounter WHERE id=NEW.encounter_id FOR KEY SHARE;
  IF EXISTS(SELECT 1 FROM core_redactiontombstone WHERE target_id=NEW.encounter_id)
  THEN RAISE EXCEPTION 'A redacted document cannot acquire clinical work'; END IF;
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.quillmd_mapping_job_scope_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE source_hash text; scope_id uuid;
BEGIN
 IF TG_OP='UPDATE' AND (NEW.encounter_id IS DISTINCT FROM OLD.encounter_id
   OR NEW.mapping_version_id IS DISTINCT FROM OLD.mapping_version_id OR NEW.user_id IS DISTINCT FROM OLD.user_id
   OR NEW.kind IS DISTINCT FROM OLD.kind) THEN RAISE EXCEPTION 'Job scope is immutable'; END IF;
 IF NEW.kind='mapping' THEN
   SELECT t.sha256,t.department_id INTO source_hash,scope_id FROM core_template t
     JOIN core_templateversion v ON v.template_id=t.id WHERE v.id=NEW.mapping_version_id;
   IF NEW.config->>'source_sha256' IS DISTINCT FROM source_hash
     OR NEW.config->>'department_id' IS DISTINCT FROM scope_id::text
     OR NEW.config->>'mapping_version_id' IS DISTINCT FROM NEW.mapping_version_id::text
   THEN RAISE EXCEPTION 'Mapping job source and tenant binding mismatch'; END IF;
 END IF;
 RETURN NEW;
END; $function$
